class Shape:
    def area(self):
        return 0

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return 3.14 * self.radius * self.radius

w = float(input())
h = float(input())
r = float(input())

rect = Rectangle(w, h)
circ = Circle(r)
print(round(rect.area(), 2))
print(round(circ.area(), 2))

