from abc import ABC, abstractmethod

class PaymentGateway(ABC):
    @abstractmethod
    def pay(self, amount):
        pass

class CreditCard(PaymentGateway):
    def pay(self, amount):
        return f'Paid ${amount} via Credit Card'

class UPI(PaymentGateway):
    def pay(self, amount):
        return f'Paid ${amount} via UPI'

gateway_type = input().strip().lower()
amount = int(input())

gw = CreditCard() if gateway_type == 'card' else UPI()
print(gw.pay(amount))

