questions.solution_code:
class Employee:
    def __init__(self, name, base_salary):
        self.name = name
        self.base_salary = base_salary

    def get_salary(self):
        return self.base_salary

class Manager(Employee):
    def __init__(self, name, base_salary, bonus):
        super().__init__(name, base_salary)
        self.bonus = bonus

    def get_salary(self):
        return self.base_salary + self.bonus

class Developer(Employee):
    def __init__(self, name, base_salary, overtime_hours, hourly_rate):
        super().__init__(name, base_salary)
        self.overtime_hours = overtime_hours
        self.hourly_rate = hourly_rate

    def get_salary(self):
        return self.base_salary + (self.overtime_hours * self.hourly_rate)

emp_type = input().strip().lower()
name = input().strip()
base = float(input())
if emp_type == 'manager':
    bonus = float(input())
    emp = Manager(name, base, bonus)
else:
    hours = float(input())
    rate = float(input())
    emp = Developer(name, base, hours, rate)
print(int(emp.get_salary()))

